	/** 
	 * jumpstart the process by instantiating2 Operator
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		operatorId = OperatorService.getOperatorInstance()
		.createOperator( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OperatorService.getOperatorInstance()
				.createOperator( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.operatorSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Operator : " + successValue.getOperatorId());
							  if (successValue.getOperatorId().equals(operatorId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOperatorList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Operator test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on operator consumed")
					);
			subscriber.operatorSubscribe( operatorId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Operator : " + successValue.getOperatorId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOperatorList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on operator for operatorId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Operator. 
	 */
	protected Operator read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Operator" );

		Operator entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Operator with primary key" );
		msg.append( operatorId );
		
		OperatorFetchOneSummary fetchOneSummary = new OperatorFetchOneSummary( operatorId );

		try {
			entity = OperatorService.getOperatorInstance().getOperator( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Operator " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Operator.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Operator." );

		StringBuilder msg = new StringBuilder( "Failed to update a Operator : " );        
		Operator entity = read();
		UpdateOperatorCommand command = generateUpdateCommand();
		command.setOperatorId(entity.getOperatorId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Operator." );

			// for use later on...
			operatorId = entity.getOperatorId();

			OperatorService proxy = OperatorService.getOperatorInstance();  

			proxy.updateOperator( command ).get();

			LOGGER.info( "-- Successfully saved Operator - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + operatorId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Operator.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Operator." );

		Operator entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Operator with id " + operatorId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Operator with id " + operatorId );

			throw e;
		}

		try{
			OperatorService.getOperatorInstance().delete( new DeleteOperatorCommand( entity.getOperatorId() ) ).get();
			LOGGER.info( "-- Successfully deleted Operator with id " + operatorId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Operator with id " + operatorId );

			throw e;
		}
	}

	/**
	 * get all Operators.
	 */
	protected List<Operator> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Operators:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Operator : " );        
		List<Operator> collection  = new ArrayList<>();

		try {
			// call the static get method on the OperatorService
			collection = OperatorService.getOperatorInstance().getAllOperator();
			assertNotNull( collection, "An Empty collection of Operator was incorrectly returned.");
			
			// Now print out the values
			Operator entity = null;            
			Iterator<Operator> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOperatorId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

